using ControlDeFinanzasIA.Domain.Enums;

namespace ControlDeFinanzasIA.Application.UseCases.Expenses.RegisterExpense;

/// <summary>
/// Immutable command to register a new expense. The identity and audit
/// timestamps are generated by the domain entity, not supplied by the caller.
/// </summary>
public sealed record RegisterExpenseCommand(
    Guid CategoryId,
    DateOnly Date,
    decimal Amount,
    Currency Currency,
    string Description,
    string? Note,
    Guid? PaymentMethodId = null);
